def win_long(path) -> str:
    """Windows 长路径支持：绝对路径加 \\?\ 前缀，突破 260 字符限制。
    非 Windows 或已是前缀时原样返回。
    """
    s = str(path)
    if os.name != "nt":
        return s
    s = os.path.abspath(s)
    if s.startswith("\\\\?\\"):
        return s
    if s.startswith("\\\\"):
        return "\\\\?\\UNC" + s[1:]
    return "\\\\?\\" + s


def lp_makedirs(path) -> None:
    os.makedirs(win_long(path), exist_ok=True)


